#!/usr/bin/env node
/**
 * Writes the gitignored src/environments/environment.local.ts.
 *
 *   node scripts/write-firebase-env.mjs            # real project, values from env vars / .env.local
 *   node scripts/write-firebase-env.mjs --emulators # local emulators, demo-mcl-portal project
 *
 * Env vars (real project): FIREBASE_API_KEY, FIREBASE_AUTH_DOMAIN, FIREBASE_PROJECT_ID,
 * FIREBASE_STORAGE_BUCKET, FIREBASE_MESSAGING_SENDER_ID, FIREBASE_APP_ID.
 * Optional: APP_PRODUCTION=false, ENABLE_GOOGLE_SIGN_IN=true.
 *
 * Never commit the generated file; it is listed in .gitignore.
 */
import { existsSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const outFile = resolve(root, 'src/environments/environment.local.ts');
const emulators = process.argv.includes('--emulators');

// Minimal .env.local loader (KEY=value lines); real env vars win.
const envFile = resolve(root, '.env.local');
if (existsSync(envFile)) {
  for (const line of readFileSync(envFile, 'utf8').split(/\r?\n/)) {
    const m = line.match(/^\s*([A-Z0-9_]+)\s*=\s*(.*)\s*$/);
    if (m && process.env[m[1]] === undefined) {
      process.env[m[1]] = m[2].replace(/^['"]|['"]$/g, '');
    }
  }
}

const keys = {
  apiKey: 'FIREBASE_API_KEY',
  authDomain: 'FIREBASE_AUTH_DOMAIN',
  projectId: 'FIREBASE_PROJECT_ID',
  storageBucket: 'FIREBASE_STORAGE_BUCKET',
  messagingSenderId: 'FIREBASE_MESSAGING_SENDER_ID',
  appId: 'FIREBASE_APP_ID',
};

let firebase;
if (emulators) {
  firebase = {
    apiKey: 'demo-api-key',
    authDomain: 'demo-mcl-portal.firebaseapp.com',
    projectId: 'demo-mcl-portal',
    storageBucket: 'demo-mcl-portal.appspot.com',
    messagingSenderId: '000000000000',
    appId: '1:000000000000:web:demo',
  };
} else {
  const missing = Object.values(keys).filter((k) => !process.env[k]);
  if (missing.length) {
    console.error(`Missing Firebase config env vars: ${missing.join(', ')}`);
    process.exit(1);
  }
  firebase = Object.fromEntries(Object.entries(keys).map(([k, env]) => [k, process.env[env]]));
}

const production = emulators ? false : process.env.APP_PRODUCTION !== 'false';
const enableGoogle = process.env.ENABLE_GOOGLE_SIGN_IN === 'true';

const contents = `// GENERATED by scripts/write-firebase-env.mjs. Do not edit or commit (gitignored).
import { Environment } from './environment.model';

export const environment: Environment = {
  production: ${production},
  appName: 'MCL Department of Florida Portal',
  departmentId: 'dof',
  departmentName: 'Department of Florida',
  ribbonRackBuilderUrl: 'https://bhartman21.github.io/RibbonRackBuilder/',
  firebase: ${JSON.stringify(firebase, null, 2).replace(/\n/g, '\n  ')},
  useEmulators: ${emulators},
  enableGoogleSignIn: ${enableGoogle},
};
`;
writeFileSync(outFile, contents);
console.log(`Wrote ${outFile} (${emulators ? 'emulators' : `project ${firebase.projectId}`})`);
